// Set only when a video clearly features one variety of Spanish.
export type VideoVariety = "Spain" | "Latin America" | "Mexico" | "Argentina" | "Colombia";

export type LessonVideo = {
  videoId: string;
  title: string;
  source: string;
  topic?: VideoTopic;
  variety?: VideoVariety;
};

